import { beforeEach, describe, expect, it, vi } from "vitest";
import {
  defaultShowToast,
  defaultUpdateToast,
  defaultDismissToast,
  defaultIsToastVisible,
  toaster,
} from "./toasterInstance";

describe("defaultShowToast", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("does not create a toast when title and description are missing", () => {
    const createSpy = vi.spyOn(toaster, "create");

    defaultShowToast({ type: "info" });

    expect(createSpy).not.toHaveBeenCalled();
    createSpy.mockRestore();
  });

  it("creates a toast when title is provided", () => {
    const createSpy = vi.spyOn(toaster, "create");

    defaultShowToast({ title: "Hello", type: "info" });

    expect(createSpy).toHaveBeenCalledWith({ title: "Hello", type: "info" });
    createSpy.mockRestore();
  });

  it("creates a toast when description is provided", () => {
    const createSpy = vi.spyOn(toaster, "create");

    defaultShowToast({ description: "Details", type: "warning" });

    expect(createSpy).toHaveBeenCalledWith({ description: "Details", type: "warning" });
    createSpy.mockRestore();
  });
});

describe("defaultUpdateToast", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("updates a toast with the given id and options", () => {
    const updateSpy = vi.spyOn(toaster, "update");

    defaultUpdateToast("test-id", { title: "Updated Title" });

    expect(updateSpy).toHaveBeenCalledWith("test-id", { title: "Updated Title" });
    updateSpy.mockRestore();
  });
});

describe("defaultDismissToast", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("dismisses a toast with the given id", () => {
    const dismissSpy = vi.spyOn(toaster, "dismiss");

    defaultDismissToast("test-id");

    expect(dismissSpy).toHaveBeenCalledWith("test-id");
    dismissSpy.mockRestore();
  });
});

describe("defaultIsToastVisible", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("returns the visibility status of a toast", () => {
    const isVisibleSpy = vi.spyOn(toaster, "isVisible").mockReturnValue(true);

    const result = defaultIsToastVisible("test-id");

    expect(isVisibleSpy).toHaveBeenCalledWith("test-id");
    expect(result).toBe(true);
    isVisibleSpy.mockRestore();
  });
});
